-- Read-only metadata and aggregate review; no customer IDs, messages, dates or record contents returned.
BEGIN TRANSACTION READ ONLY;
SELECT jsonb_build_object(
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('viewing_requests','notifications')),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'nullable',is_nullable,'default',column_default) ORDER BY table_name,ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name IN('viewing_requests','notifications')),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint WHERE conrelid IN('public.viewing_requests'::regclass,'public.notifications'::regclass)),
 'referencing_constraints',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint WHERE confrelid='public.viewing_requests'::regclass),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef) ORDER BY tablename,indexname) FROM pg_indexes WHERE schemaname='public' AND tablename IN('viewing_requests','notifications')),
 'policies',(SELECT jsonb_agg(jsonb_build_object('table',tablename,'name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY tablename,policyname) FROM pg_policies WHERE schemaname='public' AND tablename IN('viewing_requests','notifications')),
 'grants',(SELECT jsonb_agg(jsonb_build_object('table',table_name,'role',grantee,'privilege',privilege_type) ORDER BY table_name,grantee,privilege_type) FROM information_schema.table_privileges WHERE table_schema='public' AND table_name IN('viewing_requests','notifications') AND grantee IN('PUBLIC','anon','authenticated','service_role')),
 'column_acl_count',(SELECT count(*) FROM pg_attribute WHERE attrelid IN('public.viewing_requests'::regclass,'public.notifications'::regclass) AND attacl IS NOT NULL),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'function',p.proname,'body_md5',md5(p.prosrc)) ORDER BY t.tgrelid::regclass::text,t.tgname) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND t.tgrelid IN('public.viewing_requests'::regclass,'public.notifications'::regclass)),
 'viewing_permissions',(SELECT jsonb_agg(jsonb_build_object('role',r.name,'permission',p.name) ORDER BY r.name,p.name) FROM public.roles r JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.id=rp.permission_id WHERE p.name LIKE 'viewings.%'),
 'aggregates',jsonb_build_object('viewings',(SELECT count(*) FROM public.viewing_requests),'states',(SELECT coalesce(jsonb_object_agg(status,total),'{}'::jsonb) FROM(SELECT status,count(*) total FROM public.viewing_requests GROUP BY status) s),'scheduled_or_progress_missing_preferences',(SELECT count(*) FROM public.viewing_requests WHERE status IN('scheduled','in_progress') AND (preferred_date IS NULL OR preferred_time IS NULL)),'scheduled_or_progress_unassigned',(SELECT count(*) FROM public.viewing_requests WHERE status IN('scheduled','in_progress') AND assigned_to IS NULL),'oversized_messages',(SELECT count(*) FROM public.viewing_requests WHERE char_length(message)>2000),'invalid_assignees',(SELECT count(*) FROM public.viewing_requests v WHERE v.assigned_to IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.roles r ON r.id=p.role_id WHERE p.id=v.assigned_to AND p.account_status='active' AND r.name IN('administrator','sales_customer_service'))),'viewing_notifications',(SELECT count(*) FROM public.notifications WHERE related_entity_type='viewing_request'),'viewing_audits',(SELECT count(*) FROM public.audit_logs WHERE entity_type='viewing_request')),
 'last_migration',(SELECT max(version) FROM supabase_migrations.schema_migrations)
) evidence;
COMMIT;
